Model.__index = Model

-- A single hidden measurement row preserves the exact font/wrapping rules without allocating offscreen rows.
function APR.questOrderListSupport:CreateStepModel(layout, stepIndex, stepText, questInfo, color, isActiveStep)
    if not self.measureParent then
        self.measureParent = CreateFrame("Frame", nil, UIParent)
        self.measureParent:Hide()
    end
    local measurement = {scrollChild = self.measureParent, frameWidth = layout.frameWidth,
        frameOffset = layout.frameOffset, dataHeight = 0, container = self.measureRow,
        signatureParts = layout.signatureParts, measuring = true}
    local row, activeQuestId = self:AddStepFrameWithQuest(measurement, stepIndex, stepText, questInfo, color, isActiveStep)
    self.measureRow = row
    local model = setmetatable({isModel = true, stepIndex = stepIndex, stepText = stepText,
        questInfo = questInfo or {}, color = color, isActiveStep = isActiveStep,
        height = row:GetHeight(), width = layout.frameWidth, frameOffset = layout.frameOffset}, Model)
    layout.dataHeight = layout.dataHeight - model.height
    return model, activeQuestId
end--[[APR_DIAG]]; APR.questOrderListSupport.CreateStepModel = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:178:APR.questOrderListSupport:CreateStepModel#15", APR.questOrderListSupport.CreateStepModel)--[[/APR_DIAG]]

function APR.questOrderListSupport:BindStepModel(row, model, parent)
    if row.model then row.model.frame = nil end
    row.model, model.frame = model, row
    local layout = {scrollChild = parent, frameWidth = model.width, frameOffset = model.frameOffset,
        dataHeight = 0, container = row}
    self:AddStepFrameWithQuest(layout, model.stepIndex, model.stepText, model.questInfo, model.color, model.isActiveStep)
    self:SetStepFrameState(row, model.color, model.isActiveStep)
end--[[APR_DIAG]]; APR.questOrderListSupport.BindStepModel = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:195:APR.questOrderListSupport:BindStepModel#16", APR.questOrderListSupport.BindStepModel)--[[/APR_DIAG]]

function APR.questOrderListSupport:AddStepFrameWithQuest(layout, stepIndex, stepText, questInfo, color, isActiveStep)
    if layout.collectModels then return self:CreateStepModel(layout, stepIndex, stepText, questInfo, color, isActiveStep) end
    local container = layout.container or CreateFrame("Frame", nil, layout.scrollChild, "BackdropTemplate")
    container:SetParent(layout.scrollChild)
    local indexStr = tostring(stepIndex)
    local offset = 14 + 7 * string.len(indexStr)
    local frameOffset = layout.frameOffset or 0
    container.offset = offset

    local function reuseFont(font, text, width, fontColor)
        if not font then return self:CreateTextFont(container, text, width, fontColor) end
        font:SetText(text)
        font:SetWidth(width)
        font:ClearAllPoints()
        APR:SetFontStringRole(font, fontColor == "green" and "success" or "muted")
        font:Show()
        return font
    end--[[APR_DIAG]]; reuseFont = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:213:reuseFont#18", reuseFont)--[[/APR_DIAG]]
    local indexFont = reuseFont(container.indexFont, stepIndex, layout.frameWidth, color)
    local titleFont = reuseFont(container.titleFont, stepText, layout.frameWidth - offset - 5, color)
    indexFont:SetPoint("TOPLEFT", container, "TOPLEFT", 5, 0)
    titleFont:SetPoint("TOPLEFT", container, "TOPLEFT", offset, 0)

    container.indexFont = indexFont
    container.titleFont = titleFont
    container.questFontPool = container.questFontPool or {}
    container.questFonts = {}

    local questFontHeight = 0
    local activeQuestId
    local signature = { tostring(stepIndex), tostring(stepText), color or "gray", tostring(isActiveStep) }
    for i, quest in ipairs(questInfo or {}) do
        local questName = quest.questName and ' - ' .. quest.questName or ''
        local rawQuestId = quest.questID
        local questIdString = tostring(rawQuestId)
        local questText = questIdString .. questName
        local questFont = reuseFont(container.questFontPool[i], questText, layout.frameWidth - offset - 15)
        signature[#signature + 1] = questText
        container.questFontPool[i] = questFont

        if isActiveStep then
            local dashIndex = string.find(questIdString, "-")
            if dashIndex then
                activeQuestId = string.sub(questIdString, 1, dashIndex - 1)
            else
                activeQuestId = rawQuestId or questIdString
            end
        end

        questFont:SetPoint("TOPLEFT", container, "TOPLEFT", offset + 10,
            -titleFont:GetStringHeight() - 5 - questFontHeight)
        questFontHeight = questFontHeight + questFont:GetStringHeight() + 3
        container.questFonts[i] = questFont
    end
    for i = #container.questFonts + 1, #container.questFontPool do container.questFontPool[i]:Hide() end
    if layout.signatureParts then
        for _, value in ipairs(signature) do
            layout.signatureParts[#layout.signatureParts + 1] = #value .. ":" .. value
        end
    end

    container:SetWidth(layout.frameWidth)
    container:SetHeight(titleFont:GetStringHeight() + questFontHeight + frameOffset)
    container:SetPoint("TOPLEFT", layout.scrollChild, "TOPLEFT", 0, layout.dataHeight)
    layout.dataHeight = layout.dataHeight - container:GetHeight()

    if not layout.measuring then bindUncompletedStepTooltip(container, color == "gray" and questInfo or nil) end

    container:Show()

    return container, activeQuestId
end--[[APR_DIAG]]; APR.questOrderListSupport.AddStepFrameWithQuest = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:204:APR.questOrderListSupport:AddStepFrameWithQuest#17", APR.questOrderListSupport.AddStepFrameWithQuest)--[[/APR_DIAG]]

